GimCorpus.put(435,0,[[1,15,"שחטה והיא כולה וכו' עד מפני שמנונית. א\"א לא ידעתי זה מהו שהיוצא בקדשי קדשים בין לפני קבלה בין לאחר קבלה נפסל ולענין טומאה בפ' כיצד צולין בעיא ולא איפשיטא הילכך טמויי נמי מטמא ליה למה שבפנים דחבורי אוכלין כמאן דמפרתי דמו ורבינא דהוא בתרא הכי ס\"ל במס' חולין פ' בהמה המקשה ושמעתא דזבחים דלא כרבינא היא ולא חייש לטומאה אלא לבליעת בשר מבשר ואנן כרבינא סבירא לן ואיכא משום טומאה מיהו איכא למימר הך שמעתא לאו לאכשורי בשרה לאכילה קאמר אלא לאכשורי זבחא לבעלים לכפרה קאמר וכן עיקר:",1,0],[1,15,"ואח\"כ חתך פסול מפני וכו'. א\"א אפילו אחר זריקה אע\"פ שיצא חוץ לעזרה שהרי נאכל בכל ירושלים:",2,0],[1,28,"עושה שירים כיצד. א\"א סבור אני שטעה בזה שהוא סבור כשאמרו כוס עושה חבירו דחוי או שירים בקבלה בלבד אמרו אפילו בלא זריקה ואינו כן שאין השאר לא דחוי ולא שירים עד שיזרק מן האחר ואפילו קיבל הכשר תחלה וכ\"ש פסול:",1,0],[1,31,"נפסל הבשר וכו' עד וזריקה מועלת ליוצא. א\"א לא ידעתי מהו זה בשר קדשים קלים שיצא חוץ לעזרה למה לא יאכל ואולי על יוצא חוץ למחיצתו קאמר אלא שדבריו מבולבלין:",1,0],[1,33,"ואם החזירן מקטירין. א\"א זה אינו מחוור:",1,0],[2,14,"פר העלם וכו' עד כיון שיצא יצא. א\"א אני איני סובר כפירושו כי הסוגיא שלו דומה דמשום יציאה הוא הפסול והענין אינו כן אלא משום ביאת פנים הילכך צריך לפרש הבעיא פר ושעיר של יום הכפורים שהזה דמם על הבדים והוציאן להיכל כדינו וחזר והכניסן לפני ולפנים נפסלו מלהזות על הפרוכת או לא מי אמרינן מקומו היה ואינו נפסל בו או לא ואם תמצי לומר כיון דנפק נפק ושוב לא נקרא מקומו מפרוכת למזבח הזהב שהכל בהיכל מהו הא ודאי מקומו הוא או דילמא יציאה כתיבא ביה ויצא אל המזבח וכי הדר עייל ליה לבית הפרוכת ובא קרינן ביה:",1,0],[3,13,"שני אשמות וכו' עד הרי אלו ירדו. א\"א והוא שזרק דם האחד ולא נזרק דמו של זה ומשום מחוסר זמן קאתי ליה:",1,0],[3,17,"קומץ שמיצה שמנו על העצם. א\"א בנוסחא שלנו שמיצה שמנו על העצים ומה שפירש הענין לאם ירדו אם יעלו לא נהיר דבר למד מעניינו ואין הענין ההוא מדבר לירידה ועלייה אלא לענין חסרון קומץ או חסרון שמנו אם נמצא שמנו על העצים אם נחשוב אותו קודם הקטרתו שהרי עדיין לא משלה בו האור אע\"פ שנפל ע\"ג עצים שבמערכה דחבורי עולים דהיינו עצים שהם חיבור לקומץ לאו כקומץ דמו והרי חסר שמנו או דילמא כעולים דמו והרי לא חסר שמנו קודם הקטרה וזה הבעיא במנחות פרק הקומץ רבה:",1,0],[4,18,"אבל הדיוט וכו' עד הרי אלו אין מתקדשין. א\"א אין דבריו מחוורים שכל אותן דברים האמורים בתמורה לדעת ר\"ש הם דקא סבר כל דלא חזי לאלתר להקריבה לא חיילה קדושה עליה. וכן אמר על מפריש נקבה לאשם תמכר שלא במום ואולי מפני שאמר אין אני רואה דבריו של ר\"ש בפסח מכלל דבאשם רואה את דבריו. ועוד דבגמרא קא טרח לפרושי טעמא דר\"ש באשם:",1,0],[5,7,"הלוקח מעות בידו עד ק\"ו בשאר קרבנות. א\"א אני אין לי אלא קרבן חובה אבל קרבן נדבה הרי שנינו מותר עולה לעולה מותר שלמים לשלמים והטעם מי שאמר (הרי אלו שאביא מהם חטאתי או אשמי וכל מי שמחוייב קרבן שיאמר) הרי אלו שאביא מהן חובתי הרי זה פירש בפיו שאינו מפריש אלא חובתו אבל מי שאמר הרי אלו שאביא מהן עולה או שלמים מרבה בנדבה הוא:",1,0],[5,13,"מי שהיה מחוייב חטאת וכו' עד ואמר אלו לחובתי. א\"א מצאתי דבר זה בגמרא דנזיר בתוספתא שהוא בחילוף ולשון התוספתא שאם רצה להביא בהן חטאת העוף לא יביא עולת העוף (לא יביא) ומועלין בכולן ומועלין במקצתן וכו' והתוספ' יותר מתוקנת מן הגמ' ומסתבר דהכי היא דכיון דאמר הרי עלי עולה נעשה הכל חובה עליו וחטאת ועולה מעורבין בהן ולפיכך אם מת כולן ילכו לים המלח ואם היו כולן ראויים לעולה אמאי ילכו לים המלח:",1,0],[6,10,"תודה שנתערבה. א\"א והא קא ממעט באכילת זרוע בשלה:",1,0],[6,10,"ויביא בדמי היפה. א\"א אינה טעונה לחם:",2,0],[6,12,"בכור שנתערב ויאכלו כבכור. א\"א והבכור בעל מום אי זה אכילה חמורה שבו ועוד מה תיקן לבעל הפסח והיה צריך לפרש תיקונו:",1,0],[8,3,"ויראה לי שהוא. א\"א טעה טעות גדולה ואם בא לימלך היאך אומרים לו הקרב פסולין למזבח והעופות אם יעשה אותן למטה יפסלו אלא ודאי אומרים לו לא תקריב אלא כמנין חטאות שבחובה עשה אותן למטה ואם יאמר האי כלן למטה שכתב על מנין חטאות שבחובה קאמר וכן כולן למעלה שכתב מנין העולות שבחובה קאמר א\"כ מה יראה לי ואין זה צריך ראיה ועיון ואם לא יעשה אותן כתקונן היאך יהיה כשר כמנין חטאות או כמנין עולות:",1,0],[8,6,"עשה חציין למטה. א\"א זה כתב בשביל שראה במשנה בראש פ\"ג בד\"א בכהן שנמלך אבל בכהן שאינו נמלך אחת לזו ואחת לזו וכו' ומחצה כשר ומחצה פסול וכו'. וכמה לשונו מקולקל שאם עשה כל הפרידין שנתערבו חציין למעלה וחציין למטה מה לי אם שאל מה לי אם לא שאל לעולם מחצה כשר ומחצה פסול אלא שאם שאל אומרים לו אל תקריב מהן אלא כשיעור המועט ועשה אותן חציין למעלה וחציין למטה שאין מקריבין פסולין למזבח ואם בא לעשות חטאת יותר אומרים לו שמא מן המועט היא וכבר עשית חטאתיה וכן אם בא לעשות עולות אומר לו שמא מן המעוטה היא וכבר הקרבת עולותיה אבל בשלא נמלך ועשה חציין למעלה וחציין למטה כשיעור המרובה כשר שאפשר שעשה מהן חציין חטאות וחציין עולות ולא שיעלה לה לחובותיה כולן שהרי אינה יודעת כמה עשה משלה למעלה ולמטה וכמה עשה משל חברותה אלא שמביא עם חברותה בתנאי וכל מה שהוכשר בעשייתו יועיל לו עם תנאו וממעט בהשלמת חובתה:",1,0],[10,1,"בד\"א כשהביאה וכו' עד ושנים למטה. א\"א ולא ידע הכהן אי זה מין עשה למטה ואי זה מין עשה למעלה:",1,0],[10,3,"בד\"א כשהביאה הארבעה בתחלה ממין אחד וכו' עד וכן אם. א\"א דבריו מבולבלים ולא מתוקנים וצריכין הצעה גדולה וכבר הוא מפורש אצלו ושם יראה הרואה ויבין:",1,0],[12,6,"נפסל מקבלה ואילך. א\"א זה כתב לר\"א בר\"ש דבעי שני דברים המתירין ואם נתקבל הדם ונשפך כמי שנזרק דמו אבל לרבי אפילו בשחיטה לחוד קדשו ליקרב עם זבח אחר:",1,0],[12,13,"האומר הרי זו תודה ונתערבה וכו' עד אלא תרעה. א\"א מה תקנה יש בזה אלא יביא אחרת ולחמה ודמיה של זו יביא תודה בלא לחם שהיא מותר דתודה:",1,0],[12,14,"תודה שנפרסה וכו' עד או נטמאה שאר החלות. א\"א במאי עסקינן אם קודם שחיטה נפרסה אחת אמאי כולן פסולות יביא מתוך ביתו וימלא ואם לאחר זריקה הרי תורם מן השלם על הפרוס. אלא בין שחיטה לזריקה בין נפרס בין יצא בין נטמא הכל פסול דהא כלהו בחד גוונא תני להו ולא תני בהו תורם מן השלם על הפרוס ולא מן הטהור על הטמא ולא ממה שבפנים על מה שבחוץ אלא הכל פסול ולית להו תקנתא:",1,0],[13,9,"כבר ביארנו וכו' עד הרי זו הולכה. א\"א לא נהיר דסוגיין כולה כר' אלעזר דאמר לא שמה הולכה:",1,0],[14,3,"בדבר הראוי לעבודה וכו' עד מפני שהיא מן השעורים. א\"א לא מחוורא האי גירסא דא\"כ מנחת קנאות מאי איריא שהלבונה עליה תיפוק לי דקמח שעורים היא אלא נוסחא דווקנא לאפוקי מנחת העומר דחדש הוא ואין מביאין מנחות ובכורים קודם לשתי הלחם ואע\"פ שקרב העומר והותר באכילה:",1,0],[15,11,"בד\"א ששחטו בזמנו. א\"א זהו כבן בתירא ור' יהושע מכשיר:",1,0],[16,6,"חשב על הדם. א\"א כדומה לי שיש כאן שבוש:",1,0],[18,14,"והאוכל קדש וכו' עד לוקה ואינו חייב כרת. א\"א זה שבוש שכבר כתבנו למעלה שהוא בכרת:",1,0],[18,23,"כאוכל משאר בשר הזבח. א\"א דוקא בשפגל הזבח נתפגלו הם עמו אבל במחשבת עצמן לא:",1,0],[18,24,"לא משום פגול. א\"א זה לדעת ר\"ש [אבל לרבנן חייבים עליהם כרת]:",1,0],[19,3,"לפיכך נפסלו מספק. א\"א לא היתה אותה בעיא לענין פסלות אלא לענין טומאת בגדים שהן מטמאין משיצאו חוץ לחומת העזרה וביציאת רובן הם מטמאין וקא מבעיא ליה יציאת רובן במיעוט אבר:",1,0],[19,3,"וכן אם נשאום. א\"א אף זו לענין טומאת בגדים ומי שיש לו לב יבין זאת:",2,0],[19,4,"למי שעבר ואכל. א\"א לספק מעילה:",1,0],[19,9,"אינן טעונין שריפה. א\"א שמצאן חלוצים מפסולי קדושה:",1,0],[19,13,"חוץ מדשן המזבח. א\"א הרמת הדשן:",1,0],[19,15,"נאמן. א\"א כל שבידו נאמן:",1,0]]);
